// Keep recovery scoped to Notes; never persist uploaded accounting documents.
const nt145BackupKey='fc_notes_backup_v145';
let nt145StorageBlocked=false;
function nt145ReadNotes(raw){
  const data=JSON.parse(raw);
  if(!data||!Array.isArray(data.notes)||!data.notes.every(valid))throw Error('format');
  return {notes:data.notes.map(normalize),theme:data.theme==='light'?'light':'dark'};
}
function nt145LoadNotes(){
  let raw=null;
  try{
    raw=window.SWWorkspace.storage.getItem(key);
    if(!raw)return;
    const data=nt145ReadNotes(raw);
    notes=data.notes;theme=data.theme;lastSaved=JSON.stringify({version:1,theme,notes});
    $('ntSaveState').textContent='✓ Notlar geri yüklendi';
  }catch(e){
    try{
      const recovered=nt145ReadNotes(window.SWWorkspace.storage.getItem(nt145BackupKey));
      // Preserve the unreadable original before recovering the previous good save.
      if(raw)window.SWWorkspace.storage.setItem('fc_notes_unreadable_v145',raw);
      notes=recovered.notes;theme=recovered.theme;
      lastSaved=JSON.stringify({version:1,theme,notes});
      window.SWWorkspace.storage.setItem(key,lastSaved);
      $('ntSaveState').textContent='Son sağlam not kaydı geri yüklendi. Notlarını kontrol et.';
    }catch(backupError){
      nt145StorageBlocked=true;
      $('ntSaveState').textContent='Not kaydı okunamadı; üzerine yazılmadı. Not yedeğini “Yedekten ekle” ile aç.';
    }
  }
}
function save(){
  if(nt145StorageBlocked){$('ntSaveState').textContent='Önce not yedeğini aç. Mevcut kayıt ve Windows hatırlatmaları korunuyor.';return false;}
  try{
    const data=JSON.stringify({version:1,theme,notes});
    // A failed secondary backup must not prevent the main save.
    if(lastSaved&&lastSaved!==data){try{window.SWWorkspace.storage.setItem(nt145BackupKey,lastSaved);}catch(backupError){}}
    window.SWWorkspace.storage.setItem(key,data);lastSaved=data;
    $('ntSaveState').textContent='✓ Kaydedildi';nt144ScheduleSync();return true;
  }catch(e){$('ntSaveState').textContent='Kaydedilemedi. Notları yedekleyin; bu pencereyi kapatmayın.';return false;}
}

