    for(let y=-6;y<=6;y++){const row=document.createElement('div');for(let x=Math.max(-6,-y-6);x<=Math.min(6,-y+6);x++){const radius=Math.max(Math.abs(x),Math.abs(y),Math.abs(x+y)),angle=(Math.atan2(y*.866,x+y*.5)*180/Math.PI+360)%360,h=radius===0?'#ffffff':hsl(angle,Math.min(100,radius*18),90-radius*8);const b=nt126Button('',h,()=>set(h));b.className='nt126-hexagon';b.style.background=h;row.append(b);}honey.append(row);}
    for(let i=0;i<12;i++){const v=Math.round(255-i*255/11).toString(16).padStart(2,'0'),h='#'+v.repeat(3),b=nt126Button('',h,()=>set(h));b.style.background=h;b.className='nt126-hexagon';d.querySelector('.nt126-gray').append(b);}
