 // Web reminders run only while this page is open; no local desktop bridge.
 let nt144SyncTimer=null;
 const sw177Notified=new Map();
 function nt144Status(message){$('nt144Status').textContent=message;$('nt144Enable').textContent='Tarayıcı bildirimine izin ver';}
 function nt144Sync(){
  if(nt145StorageBlocked)return false;
  const now=Date.now();let pending=0;
  notes.forEach(n=>{
   if(!n.remind||n.done||n.ack||!n.due)return;
   const due=new Date(n.due).getTime();if(!Number.isFinite(due))return;
   if(due>now){pending++;return;}
   if(sw177Notified.get(n.id)===due)return;
   sw177Notified.set(n.id,due);
   if('Notification' in window&&Notification.permission==='granted'){
    try{new Notification(n.title,{body:n.body.slice(0,1000),tag:'sw-note-'+n.id});}catch(e){if(window.sw177Notify)window.sw177Notify('Hatırlatma: '+n.title);}
   }else if(window.sw177Notify)window.sw177Notify('Hatırlatma: '+n.title);
  });
  nt144Status(pending+' bekleyen hatırlatma. Web bildirimi yalnızca bu sayfa açıkken çalışır.');return true;
 }
 function nt144ScheduleSync(){clearTimeout(nt144SyncTimer);nt144SyncTimer=setTimeout(nt144Sync,250);}
 function nt144CheckDesktop(){nt144Sync();}
