 function nt141BorderIcon(mode){const paths={none:'',outer:'M4 4h16v16H4z',inside:'M12 4v16M4 12h16',all:'M4 4h16v16H4zM12 4v16M4 12h16',top:'M4 4h16',bottom:'M4 20h16',left:'M4 4v16',right:'M20 4v16',innerH:'M4 12h16',innerV:'M12 4v16'};return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4h16v16H4zM12 4v16M4 12h16" fill="none" stroke="#a8a8a8" stroke-dasharray="1 2"/><path d="'+paths[mode]+'" fill="none" stroke="#111" stroke-width="1.5"/></svg>';}
 nt141Border.innerHTML='<header>Hücreleri Biçimlendir<button type="button" data-close aria-label="Kapat">×</button></header><div class="nt141-tab">Kenarlık</div><div class="nt141-border-body"><fieldset><legend>Çizgi</legend><label>Stil:</label><div class="nt141-line-grid">'+nt141Styles.map(([s,label])=>'<button type="button" data-line="'+s+'" title="'+label+'" aria-label="'+label+'">'+(s==='none'?'Yok':'<i style="border-top:'+s+' #000"></i>')+'</button>').join('')+'</div><label class="nt141-line-color">Renk:<input type="color" value="#000000" aria-label="Çizgi rengi"></label></fieldset><section><fieldset class="nt141-presets"><legend>İlk Ayarlar</legend>'+[['none','Yok'],['outer','Çerçeve'],['inside','İç'],['all','Tümü']].map(([m,label])=>'<button type="button" data-preset="'+m+'">'+nt141BorderIcon(m)+'<span>'+label+'</span></button>').join('')+'</fieldset><fieldset class="nt141-preview-field"><legend>Kenarlık</legend><div class="nt141-edge-column">'+['top','innerH','bottom'].map(m=>'<button type="button" data-edge="'+m+'" title="'+nt141Modes[m]+'" aria-label="'+nt141Modes[m]+'">'+nt141BorderIcon(m)+'</button>').join('')+'</div><div class="nt141-preview"><span>Metin</span><span>Metin</span><span>Metin</span><span>Metin</span>'+Object.keys(nt141Modes).map(m=>'<button type="button" class="nt141-preview-edge nt141-preview-'+m+'" data-edge="'+m+'" title="'+nt141Modes[m]+'" aria-label="Önizleme: '+nt141Modes[m]+'"><i></i></button>').join('')+'</div><div class="nt141-edge-row">'+['left','innerV','right'].map(m=>'<button type="button" data-edge="'+m+'" title="'+nt141Modes[m]+'" aria-label="'+nt141Modes[m]+'">'+nt141BorderIcon(m)+'</button>').join('')+'</div></fieldset></section></div><p>Çizgi desenini ve rengini seçip önizlemede değiştirmek istediğin kenara tıkla.</p><footer><button type="button" data-ok>Tamam</button><button type="button" data-close>İptal</button></footer>';
 function nt141OpenBorder(n){nt141Fill.hidden=true;const range={...nt133Range()};nt141BorderDraft={id:n.id,range,format:JSON.parse(JSON.stringify(nt133Fmt(n))),line:'1px solid',color:'#000000',preview:{}};const cell=root.querySelector('[data-note="'+CSS.escape(n.id)+'"] [data-cellbox="'+range.r1+','+range.c1+'"]');if(cell){const cs=getComputedStyle(cell);for(const k of ['top','right','bottom','left'])nt141BorderDraft.preview[k]=cs.getPropertyValue('border-'+k);}nt141Border.querySelector('input').value='#000000';nt141Border.querySelectorAll('[data-line]').forEach(b=>b.classList.toggle('active',b.dataset.line==='1px solid'));nt141Preview();nt141Border.showModal();}
 function nt141Preview(){const d=nt141BorderDraft;for(const key of Object.keys(nt141Modes)){const el=nt141Border.querySelector('.nt141-preview-'+key+' i'),value=d.preview[key]||'0';el.style.cssText='';el.style[key==='left'||key==='right'||key==='innerV'?'borderLeft':'borderTop']=value;}}
 function nt141BorderSet(mode,toggle=false){const d=nt141BorderDraft,n=notes.find(n=>n.id===d.id),r=d.range,f=d.format;if(!n)return;const style=d.line==='none'?'0':d.line+' '+d.color;const edges=mode==='all'||mode==='none'?Object.keys(nt141Modes):mode==='outer'?['top','right','bottom','left']:mode==='inside'?['innerH','innerV']:[mode];
  function set(y,x,side,value){if(y<0||x<0||y>=n.table.rows||x>=n.table.cols)return;const cover=nt133Cover(f,y,x),key=cover?.key||y+','+x,st=f.cells[key]||={};if(st.border!==undefined){for(const k of ['Top','Right','Bottom','Left'])if(st['border'+k]===undefined)st['border'+k]=st.border;delete st.border;}st['border'+side]=value;}
  for(const edge of edges){const value=mode==='none'?'0':toggle&&d.preview[edge]===style?'0':style;d.preview[edge]=value;
   if(edge==='top'||edge==='bottom'){const y=edge==='top'?r.r1:r.r2;for(let x=r.c1;x<=r.c2;x++){set(y,x,edge==='top'?'Top':'Bottom',value);set(y+(edge==='top'?-1:1),x,edge==='top'?'Bottom':'Top',value);}}
   if(edge==='left'||edge==='right'){const x=edge==='left'?r.c1:r.c2;for(let y=r.r1;y<=r.r2;y++){set(y,x,edge==='left'?'Left':'Right',value);set(y,x+(edge==='left'?-1:1),edge==='left'?'Right':'Left',value);}}
   if(edge==='innerH')for(let y=r.r1;y<r.r2;y++)for(let x=r.c1;x<=r.c2;x++){const a=nt133Cover(f,y,x),b=nt133Cover(f,y+1,x);if(a&&b&&a.key===b.key)continue;set(y,x,'Bottom',value);set(y+1,x,'Top',value);}
   if(edge==='innerV')for(let x=r.c1;x<r.c2;x++)for(let y=r.r1;y<=r.r2;y++){const a=nt133Cover(f,y,x),b=nt133Cover(f,y,x+1);if(a&&b&&a.key===b.key)continue;set(y,x,'Right',value);set(y,x+1,'Left',value);}
  }nt141Preview();
 }
